enum HttpMethod {
  Get = "GET",
  Post = "POST",
}

const enum CacheTTL {
  Short = 60,
  Long = 3600,
}

const ttl = CacheTTL.Long;  // compiles to: const ttl = 3600;

const STATUS = {
  Pending: "pending",
  Done: "done",
  Failed: "failed",
} as const;

type Status = typeof STATUS[keyof typeof STATUS];
// "pending" | "done" | "failed"

function isDone(s: Status): boolean {
  return s === STATUS.Done;
}
